<?php

declare(strict_types=1);

namespace RobinsonRyan\Mailroom\Models\Concerns;

use Illuminate\Database\Eloquent\Model;

/**
 * UUID v7 keys, generated by the column's uuidv7() default, and the configurable
 * table prefix. `$incrementing = true` means "the database assigns the key", which
 * compiles the insert with `returning "id"` and hydrates the key onto the model.
 *
 * @mixin Model
 */
trait MailroomModel
{
    public function initializeMailroomModel(): void
    {
        $this->incrementing = true;
        $this->keyType = 'string';
    }

    public function getTable(): string
    {
        return config('mailroom.table_prefix', 'mailroom_').$this->baseTable();
    }

    abstract protected function baseTable(): string;
}
